import os

def safe_upload_path(upload_dir: str, filename: str) -> str:
    safe_filename = os.path.basename(filename)
    if os.path.isabs(filename) or safe_filename != filename:
        raise ValueError("Filename would escape upload_dir")
    return os.path.join(upload_dir, safe_filename)
